const input = $input.first().json || {};
const headers = input.headers || {};
const expected = String($env.BSM_SEO_COPILOT_TOKEN || '');
const received = String(headers.authorization || headers.Authorization || '');
const wanted = `Bearer ${expected}`;
function safeEqual(left, right) {
  let mismatch = left.length ^ right.length;
  const length = Math.max(left.length, right.length);
  for (let index = 0; index < length; index++) {
    mismatch |= (left.charCodeAt(index) || 0) ^ (right.charCodeAt(index) || 0);
  }
  return mismatch === 0;
}
const authorised = expected.length >= 32 && safeEqual(received, wanted);
return [{ json: { ...input, authorised } }];

const input = $input.first().json || {};
const body = input.body;
const tasks = ['keyphrase', 'metadesc', 'title', 'subheadings', 'outline', 'content'];
const valid = !!body && typeof body === 'object' && !Array.isArray(body) && JSON.stringify(body).length <= 32768 && tasks.includes(String(body.task || 'keyphrase').toLowerCase());
return [{ json: { ...input, valid } }];

const body = $input.first().json.body || {};
const text = (value, limit) => String(value || '').trim().slice(0, limit);
const task = text(body.task || 'keyphrase', 20).toLowerCase();
const title = text(body.title, 300);
const excerpt = text(body.excerpt, 4000);
const category = text(body.category, 200);
const type = text(body.type || 'post', 100);
const keyphrase = text(body.keyphrase, 200);
const target = text(body.target, 300);
const count = Math.max(1, Math.min(6, Number.parseInt(body.count, 10) || 3));
const words = Math.max(100, Math.min(2000, Number.parseInt(body.words, 10) || 600));
const site = body.site && typeof body.site === 'object' ? body.site : {};
const siteName = text(site.name, 200);
const previous = body.previous && typeof body.previous === 'object' && !Array.isArray(body.previous) ? body.previous : {};
const variation = Math.max(0, Math.min(1000, Number.parseInt(body.variation, 10) || 0));
const seed = text(body.seed, 100);
const context = `Site: ${siteName}\nContent type: ${type}\n${category ? `Category: ${category}\n` : ''}Title: ${title}\n${excerpt ? `Excerpt: ${excerpt}` : ''}`;
const prior = task === 'keyphrase' ? [previous.keyphrase, previous.related] : [previous[task]];
const seen = prior.map(value => text(value, 500)).filter(Boolean);
const avoid = variation > 1 && seen.length ? `\nProduce a meaningfully different result from: ${seen.join(' | ')}${seed ? `\nVariation token: ${seed}` : ''}` : '';
let prompt;
let maxTokens;
if (task === 'metadesc') {
  maxTokens = 120;
  prompt = `Write one active-voice SEO meta description of 120 to 140 characters, never over 155.${keyphrase ? ` Naturally include "${keyphrase}".` : ''} Return only plain text.${avoid}\n\n${context}`;
} else if (task === 'title') {
  maxTokens = 60;
  prompt = `Write one clear SEO title, 50 to 60 characters, with the main topic first.${keyphrase ? ` Naturally include "${keyphrase}".` : ''} Return only plain text.${avoid}\n\n${context}`;
} else if (task === 'subheadings') {
  maxTokens = 220;
  prompt = `Return exactly ${count} distinct H2 subheadings, each 3 to 8 words, as a JSON array of strings only.${keyphrase ? ` Include "${keyphrase}" or a close variant in at least one.` : ''}\n\n${context}`;
} else if (task === 'outline') {
  maxTokens = 320;
  prompt = `Return exactly ${count} distinct content sections to add, each 4 to 12 words, as a JSON array of strings only.${keyphrase ? ` Keep them centered on "${keyphrase}".` : ''}\n\n${context}`;
} else if (task === 'content') {
  maxTokens = Math.min(4000, Math.round(words * 2.2) + 200);
  prompt = target
    ? `Write approximately ${words} words of plain body copy for only this section: "${target}". Do not output the heading.${keyphrase ? ` Use "${keyphrase}" naturally.` : ''}\n\n${context}`
    : `Write approximately ${words} words of helpful plain body copy. No page title, metadata, HTML, or markdown.${keyphrase ? ` Center it on "${keyphrase}" naturally.` : ''}\n\n${context}`;
} else {
  maxTokens = 200;
  prompt = `Return exactly ${count} distinct SEO keyphrases of 2 to 4 words as a JSON array of strings only. Put the best primary phrase first.${avoid}\n\n${context}`;
}
const temperature = variation > 1 ? Math.min(1, 0.55 + variation * 0.1) : 0.3;
return [{ json: { task, requestBody: { messages: [{ role: 'user', content: [{ text: prompt }] }], inferenceConfig: { maxTokens, temperature } } } }];

const body = $input.first().json || {};
const content = body.output && body.output.message && Array.isArray(body.output.message.content) ? body.output.message.content : [];
const part = content.find(item => item && typeof item.text === 'string');
return [{ json: { text: part ? part.text.trim().slice(0, 20000) : '' } }];
